    }

    // Check finiteness of covariance matrix elements
    for (size_t i = 0; i < 3; i++) {
        for (size_t j = 0; j < 3; j++) {
            if (!isfinite(covariance_i->m[i][j])) {
                for (size_t k = 0; k < 3; k++) {
                    for (size_t l = 0; l < 3; l++) {
                        covariance_b->m[k][l] = 0.0;
                    }
                }
                return ADCS_E_RANGE;
            }
        }
    }

    // Check degeneracy
    double norm_sq = q_bi->w * q_bi->w + q_bi->x * q_bi->x + q_bi->y * q_bi->y + q_bi->z * q_bi->z;
    if (norm_sq <= ADCS_EPS_NORM) {
        for (size_t i = 0; i < 3; i++) {
            for (size_t j = 0; j < 3; j++) {
                covariance_b->m[i][j] = 0.0;
            }
        }
        return ADCS_E_DEGENERATE;
    }

    // Normalize quaternion
    adcs_quat_t q_norm;
    adcs_status_t status = adcs_quat_normalize(q_bi, &q_norm);
    if (status != ADCS_OK) {
        for (size_t i = 0; i < 3; i++) {
            for (size_t j = 0; j < 3; j++) {
                covariance_b->m[i][j] = 0.0;
            }
        }
        return status;
    }

    // Build DCM from normalized quaternion
    adcs_mat3_t C_BI = adcs_quat_to_dcm_bi(&q_norm);

