                return ADCS_E_RANGE;
            }
        }
    }

    /* Normalize quaternion */
    adcs_status_t status = adcs_quat_normalize(q_bi, &q_norm);
    if (status != ADCS_OK) {
        /* On degeneracy, output zero covariance as per failure contract */
        for (size_t i = 0; i < 3; i++) {
            for (size_t j = 0; j < 3; j++) {
                covariance_b->m[i][j] = 0.0;
            }
        }
        return ADCS_E_DEGENERATE;
    }

    /* Build DCM from scalar-first q */
    c_bi = adcs_quat_to_dcm_bi(&q_norm);

    /* Compute P_B = C_BI * P_I * C_BI^T */
    /* Step 1: M = C_BI * P_I */
    m = adcs_mat3_mul(&c_bi, covariance_i);

    /* Step 2: P_B = M * C_BI^T */
    c_bi_t = adcs_mat3_transpose(&c_bi);
    p_b = adcs_mat3_mul(&m, &c_bi_t);

    /* Output transformed covariance */
    *covariance_b = p_b;

    return ADCS_OK;
}

